  "drs.conversionAdviceDesc":
    "Если включено, в ежедневный отчёт руководителя добавляются конверсия лидов каждого менеджера по всем продажам, реальные проблемы из всех его проанализированных звонков и общая конверсия менеджеров. По умолчанию выключено. Действует только для текущего бизнеса.",
